import json,pathlib,random
p=pathlib.Path(__file__).resolve().parents[2]/'research/2026-10-01/ati-live';rows=json.loads((p/'full-ranked.json').read_text())
items=[
('leopard','A-2023-00105','What was publicly reported about Canada supplying additional Leopard 2 tanks, a recovery vehicle and 155mm ammunition in February 2023?','Canada February 2023 additional Leopard 2 tanks armoured recovery vehicle 155mm ammunition Ukraine'),
('china-permits','A-2025-01773','Is the specific 2025 nuclear-related dual-use export decision identified publicly? Other China permit notes are merged for search triage; no approval or exporter is established.','Canada "00390-2025" nuclear dual use export permit China'),
('ukraine-budget','A-2022-01326','What public evidence identifies how the remaining 2022 $500 million Ukraine assistance budget was allocated?','Canada 2022 remainder 500 million military aid Ukraine spending allocation'),
('armoured-vehicles','A-2023-01996','Was the recommendation to donate 50 armoured vehicles to Ukraine already publicly reported?','Canada 50 armoured vehicles Ukraine donation December 2023'),
('gac-assignments','A-2025-02439','What explains exclusion of traditional employees from round 3 of 2026 GAC assignments? The summary wording is not a verified finding.','Global Affairs Canada 2026 assignments round 3 traditional employees excluded'),
('israel-maple','A-2023-03335','Recover the article named in the request and distinguish its published claims from still-unseen internal correspondence.','The Maple January 30 2024 Trudeau Government Admits Authorized New Military Exports Israel October 7'),
('nanisivik','A-2025-02587','What public record identifies the storage-tank compliance order, its conditions and remedy at Nanisivik?','Nanisivik naval facility environmental protection compliance order storage tank 2025'),
('ukraine-mines','A-2022-01530','What is documented about Ukrainian anti-personnel mine use in 2022, and is the separate Canadian-volunteer allegation evidenced?','Ukraine Canadian volunteer fighters anti personnel mines Ottawa Treaty 2022'),
('involuntary-care','A-2025-01384','Does public CAF policy already explain consent and involuntary mental-health admission?','Canadian Armed Forces policy involuntary admission mental health psychiatric consent'),
('biometrics','A-2025-00181','What public authority and safeguards govern collection of Canadian personnel biometric data during 2025 training?','Canadian Armed Forces 2025 biometric training Canadian citizens standing authority collect data'),
('audit-middle-east','A-2025-00661','Is the June 2025 CAF Middle East personnel movement already publicly explained?','Canada Canadian Armed Forces personnel Middle East June 2025 evacuation'),
('audit-petawawa','A-2024-00225','Can public sources identify a concrete safety issue at Petawawa Building Q-103 or its golf club?','Petawawa "Q-103" golf club safety'),
('audit-medical-fairness','A-2025-02382','Are the requested medical-policy fairness/accommodation standards already public?','Canadian Armed Forces medical policy procedural fairness disability accommodation DMEDPOL')]
plans=[]
for lead,req,question,query in items:
 row=next(r for r in rows if r['request_number']==req)
 plans.append({'lead':lead,'request_number':req,'owner_org':row['owner_org'],'selection':'seeded lower-half audit' if lead.startswith('audit') else 'top editorial cluster','rank_score':row['rank_score'],'question':question,'queries':[query],'source_summary':row['summary_en'],'pages':row['pages'],'disposition':row['disposition']})
(p/'coverage-plans.json').write_text(json.dumps(plans,ensure_ascii=False,indent=2)+'\n')
(p/'selection-notes.md').write_text('''# Selection after full ranking\n\nAll 1,234 records were ranked. Release-based eligibility requires DA/DP and positive pages: 920 records. Chose ten high-priority editorial clusters, not ten literal highest rows. Merged repeated POL2023-0001129 tank notes; POL2022-0009116 and POL2022-0011253 budget-remainder notes as a programme question; and China permit notes 00390-2025/00657-2025 as a search cluster (not proof of the same transaction). This admitted the 2025 biometric-training record at eligible rank 15. Other country-specific permits remain in the ranking but were not automatically expanded without exporter/end-use identity.\n\nThree audits are seeded random samples from the lower half of the 920 eligible rows (seed 20261001): A-2025-00661, A-2024-00225, A-2025-02382. A-2025-00945 is a separate known-covered C22 control. Selection and model scores are exploratory and cannot measure precision/recall or causal improvement.\n''')
